p.parent.mkdir(exist_ok=True); p.write_text('''def transform(g):
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row if v not in (0, 9)}
    color = next(iter(colors))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0 or (r,c) in seen: continue
            stack = [(r,c)]; seen.add((r,c)); comp = []
            while stack:
                x,y = stack.pop(); comp.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= a < h and 0 <= b < w and g[a][b] == 0 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            comps.append(comp)
    seen = set(); marker_size = 0
    for r in range(h):
        for c in range(w):
            if g[r][c] == color and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c))
                while stack:
                    x,y=stack.pop(); marker_size += 1
                    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0 <= a < h and 0 <= b < w and g[a][b] == color and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
    out=[row[:] for row in g]
    for comp in comps:
        if len(comp) >= marker_size:
            for r,c in comp: out[r][c]=color
    return out
''')
